const bytes=value=>Uint8Array.from(atob(value.replaceAll('-','+').replaceAll('_','/')),c=>c.charCodeAt(0));
async function api(path,method='GET',body){const response=await fetch('/api/push/'+path,{method,headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const result=await response.json();if(!response.ok)throw new Error(result.error||'No se pudo activar el aviso.');return result;}
export function initPushControls(panel,doc=document){
 const section=doc.createElement('section');section.className='club-push-controls';const title=doc.createElement('strong');title.textContent='Avisos en tu móvil';const note=doc.createElement('p');note.setAttribute('role','status');note.textContent='Avisos push sin coste por mensaje, incluso con la página cerrada. No son SMS.';
 const enable=doc.createElement('button'),test=doc.createElement('button'),disable=doc.createElement('button');enable.type=test.type=disable.type='button';enable.textContent='Activar avisos en este dispositivo';test.textContent='Enviar aviso de prueba';disable.textContent='Desactivar avisos de este dispositivo';test.hidden=disable.hidden=true;enable.disabled=true;section.append(title,note,enable,test,disable);panel.insertBefore(section,panel.querySelector('.notification-list'));
 const supported='serviceWorker'in navigator&&'PushManager'in window&&'Notification'in window&&window.isSecureContext;
 async function registration(){return navigator.serviceWorker.register('/sw.js',{scope:'/'}).then(()=>navigator.serviceWorker.ready);}
 async function update(){section.querySelector('.club-push-login')?.remove();if(!supported){note.textContent='Este navegador no admite avisos push. En iPhone, añade la web a la pantalla de inicio y ábrela desde allí (iOS 16.4 o posterior).';return;}try{const response=await fetch('/api/admin/session');if(!response.ok){enable.disabled=true;test.hidden=disable.hidden=true;note.textContent='Inicia sesión como administrador para activar tus avisos del móvil.';const link=doc.createElement('a');link.className='club-push-login';link.href='admin.html';link.textContent='Entrar como administrador';section.append(link);return;}enable.disabled=false;const current=await navigator.serviceWorker.getRegistration('/'),subscription=await current?.pushManager.getSubscription();const registered=subscription?await api('status','POST',{endpoint:subscription.endpoint}):null;if(subscription&&registered?.registered&&Notification.permission==='granted'){test.hidden=disable.hidden=false;enable.hidden=true;note.textContent='Avisos push activados en este dispositivo. Usa la prueba para comprobar su recepción.';}else{enable.hidden=false;test.hidden=disable.hidden=true;}if(Notification.permission==='denied')note.textContent='Los avisos están bloqueados. Permítelos en los ajustes de notificaciones de este navegador.';}catch{note.textContent='No se pudo comprobar la configuración. Vuelve a abrir la campana.';}}
 enable.addEventListener('click',async()=>{enable.disabled=true;try{const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Debes permitir las notificaciones en este dispositivo. En iPhone, abre la web añadida a la pantalla de inicio.');const reg=await registration(),key=await api('key');const subscription=await reg.pushManager.getSubscription()||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:bytes(key.publicKey)});await api('subscription','POST',{endpoint:subscription.endpoint});enable.hidden=true;test.hidden=disable.hidden=false;note.textContent='Suscripción guardada. Pulsa Enviar aviso de prueba para comprobar que llega al móvil.';}catch(error){note.textContent=error.message;}finally{enable.disabled=false;}});
 test.addEventListener('click',async()=>{test.disabled=true;try{await api('test','POST',{});note.textContent='Se ha solicitado el aviso de prueba. Comprueba las notificaciones de tu móvil.';}catch(error){note.textContent=error.message;}finally{test.disabled=false;}});
 disable.addEventListener('click',async()=>{disable.disabled=true;try{const reg=await navigator.serviceWorker.getRegistration('/'),subscription=await reg?.pushManager.getSubscription();if(subscription){await api('subscription','DELETE',{endpoint:subscription.endpoint});await subscription.unsubscribe();}enable.hidden=false;test.hidden=disable.hidden=true;note.textContent='Avisos desactivados en este dispositivo.';}catch(error){note.textContent=error.message;}finally{disable.disabled=false;}});
 window.addEventListener('club-session-change',()=>void update());void update();
}
